import{_ as e,o as d,c as o,a2 as r}from"./chunks/framework.Bg-Zxr5O.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/CTABLES-Implicit-Categories.md","filePath":"manual-en/CTABLES-Implicit-Categories.md","lastUpdated":1785684581000}'),a={name:"manual-en/CTABLES-Implicit-Categories.md"};function i(s,t,c,n,l,p){return d(),o("div",null,[...t[0]||(t[0]=[r(`<h4 id="_15-7-5-2-implicit-categories" tabindex="-1">15.7.5.2 Implicit Categories <a class="header-anchor" href="#_15-7-5-2-implicit-categories" aria-label="Permalink to &quot;15.7.5.2 Implicit Categories&quot;">​</a></h4><p>In the absence of an explicit list of categories, <code>CATEGORIES</code> allows <code>KEY</code>, <code>ORDER</code>, and <code>MISSING</code> to specify how to select and sort categories.</p><p>The <code>KEY</code> setting specifies the sort key. By default, or with <code>KEY=VALUE</code>, categories are sorted by default. Categories may also be sorted by value label, with <code>KEY=LABEL</code>, or by the value of a summary function, e.g. <code>KEY=COUNT</code>.</p><p>By default, or with <code>ORDER=A</code>, categories are sorted in ascending order. Specify <code>ORDER=D</code> to sort in descending order.</p><p>User-missing values are excluded by default, or with <code>MISSING=EXCLUDE</code>. Specify <code>MISSING=INCLUDE</code> to include user-missing values. The system-missing value is always excluded.</p><p>The following example syntax and output show how <code>MISSING=INCLUDE</code> causes missing values to be included in a category list.</p><pre><code>CTABLES /TABLE freqOfDriving.
CTABLES /TABLE freqOfDriving
        /CATEGORIES VARIABLES=freqOfDriving MISSING=INCLUDE.
</code></pre><table tabindex="0"><thead><tr><th></th><th></th><th>Count</th></tr></thead><tbody><tr><td>1. How often do you usually drive a car or other motor vehicle?</td><td>Every day</td><td>4667</td></tr><tr><td>Several days a week</td><td>1274</td><td></td></tr><tr><td>Once a week or less</td><td>361</td><td></td></tr><tr><td>Only certain times a year</td><td>130</td><td></td></tr><tr><td>Never</td><td>540</td><td></td></tr><tr><td></td><td></td><td>Count</td></tr><tr><td>1. How often do you usually drive a car or other motor vehicle?</td><td>Every day</td><td>4667</td></tr><tr><td>Several days a week</td><td>1274</td><td></td></tr><tr><td>Once a week or less</td><td>361</td><td></td></tr><tr><td>Only certain times a year</td><td>130</td><td></td></tr><tr><td>Never</td><td>540</td><td></td></tr><tr><td>Don&#39;t know</td><td>8</td><td></td></tr><tr><td>Refused</td><td>19</td><td></td></tr></tbody></table>`,8)])])}const h=e(a,[["render",i]]);export{m as __pageData,h as default};
